(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.02+t*0.32)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.45)*8 + Math.sin((x+w1x)*0.028-t*0.38)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 2.1, 0.88],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*55, 0.075, 1.8, 1.12],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*65, 0.06, 2.4, 0.92],
    [300+Math.cos(t*0.7+0.5)*85, 30+Math.sin(t*0.5+5)*45, 0.085, 2.0, 1.0]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const fade = w*Math.exp(-d*0.003);
    aS += (Math.sin(d*f-t*sp)+Math.sin(d*f*1.618-t*sp*0.618))*fade;
    iS += (Math.sin(d*f*0.7+t*sp*0.6+1.5)+Math.sin(d*f*0.43-t*sp*0.8+2.8))*fade;
    cS += Math.cos(d*f*0.5+t*sp*0.4)*fade;
  }
  const act=aS/10, inh=iS/10, cor=cS/10;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1))/2
    + Math.sin((sx+sy)*0.1+t*2.5)*0.18
    + Math.sin((sx-sy)*0.08-t*2)*0.18
    + Math.sin(sx*0.06*Math.cos(t*0.1)+sy*0.04*Math.sin(t*0.15)+t*1.8)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.038+ang*4-t*1.2))*0.35
    + Math.sin(dist*0.02-ang*7+t*0.8)*0.15;
  const radPulse = Math.sin(dist*0.04-t*2)*0.2*Math.exp(-dist*0.005);
  const lapA = Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3;
  const cell = Math.tanh(lapA*1.5)*0.25;
  const rd = act - inh*0.65 + cor*0.3 + bg*0.25 + spiral + radPulse;
  const reaction = Math.tanh(rd*2.0);
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.06;
  const blend = reaction*0.7 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.72?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const glow = Math.max(0, 1-dist*0.004)*0.15+0.85;
  const pal = [
    [6,14,58],[12,45,88],[18,85,105],[25,130,125],
    [45,165,135],[120,185,110],[195,185,70],
    [220,155,65],[215,110,70],[185,65,65],
    [130,35,70],[70,22,65],[30,15,60],[6,14,58]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const br = lum*edge*glow;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*br)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*br)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*br)|0
  ];
}
